tests:
test({ sr: 'pozdravlja po imenu', en: 'greets by name' }, () => {
  expect(greet('Ana')).toBe('Hello, Ana!');
});
test({ sr: 'bez argumenta koristi Guest', en: 'without an argument it uses Guest' }, () => {
  expect(greet()).toBe('Hello, Guest!');
});
test({ sr: 'undefined je isto što i bez argumenta', en: 'undefined is the same as no argument' }, () => {
  expect(greet(undefined)).toBe('Hello, Guest!');
});

hiddenTests:
test('an empty text is not replaced', () => {
  expect(greet('')).toBe('Hello, !');
});
test('zero is not replaced', () => {
  expect(greet(0)).toBe('Hello, 0!');
});
test('null is not replaced', () => {
  expect(greet(null)).toBe('Hello, null!');
});
test('the name Guest passed on purpose', () => {
  expect(greet('Guest')).toBe('Hello, Guest!');
});
test('every call is independent', () => {
  expect(greet('Ana')).toBe('Hello, Ana!');
  expect(greet()).toBe('Hello, Guest!');
  expect(greet('Marko')).toBe('Hello, Marko!');
});

solutions.code:
function greet(name) {
  if (name === undefined) name = 'Guest';
  return 'Hello, ' + name + '!';
}
